*, *::before, *::after { box-sizing: border-box; margin: 0; padding: 0; }

:root {
  --green: #00824A;
  --green-hover: #006B3C;
  --green-light: #E8F5EE;
  --forest: #32462F;
  --cream: #F3CEA1;
  --cream-light: #FFF8F0;
  --cream-bg: #FDF6EC;
  --white: #FFFFFF;
  --gray-50: #F9FAFB;
