.promo-card.forest-bg .promo-card-content p { opacity: 0.85; }
.promo-card.white-bg { background: var(--white); border: 1px solid var(--gray-200); }

.promo-full { border-radius: var(--radius-lg); overflow: hidden; min-height: 320px; display: flex; align-items: center; padding: 48px 56px; margin-bottom: 24px; }
.promo-full-content { max-width: 520px; }
.promo-full-content h2 { font-size: 2rem; margin-bottom: 12px; letter-spacing: -0.01em; }
.promo-full-content p { font-size: 1rem; line-height: 1.7; margin-bottom: 28px; }

/* ===== SEASONAL CARDS ===== */
.seasonal-grid { display: grid; grid-template-columns: repeat(2, 1fr); gap: 24px; }
.seasonal-card { border-radius: var(--radius-lg); overflow: hidden; min-height: 400px; position: relative; display: flex; align-items: flex-end; }
.seasonal-card-bg { position: absolute; inset: 0; display: flex; align-items: center; justify-content: center; font-size: 0.875rem; color: rgba(255,255,255,0.6); }
.seasonal-card-content { position: relative; z-index: 2; padding: 40px; width: 100%; background: linear-gradient(to top, rgba(0,0,0,0.65) 0%, transparent 100%); }
.seasonal-card-content h2 { font-size: 1.75rem; color: var(--white); margin-bottom: 8px; }
.seasonal-card-content p { color: rgba(255,255,255,0.9); margin-bottom: 24px; font-size: 0.9375rem; line-height: 1.6; }
.seasonal-fruity { background: linear-gradient(135deg, #FF8C42 0%, #D4533B 100%); }
.seasonal-spring { background: linear-gradient(135deg, #A78BDB 0%, #7C5BAF 100%); }

/* ===== NONDAIRY BANNER ===== */
.nondairy-banner { background: var(--cream-bg); border-radius: var(--radius-lg); padding: 48px 56px; display: flex; align-items: center; gap: 48px; }
.nondairy-content { flex: 1; }
.nondairy-content h2 { font-size: 2rem; color: var(--forest); margin-bottom: 12px; }
.nondairy-content p { color: var(--text-light); margin-bottom: 28px; line-height: 1.7; }
.nondairy-visual { flex: 0 0 300px; height: 200px; background: linear-gradient(135deg, var(--cream) 0%, #E8D5B5 100%); border-radius: var(--radius-md); display: flex; align-items: center; justify-content: center; color: var(--text-light); font-size: 0.875rem; }

/* ===== MENU PAGE ===== */
.breadcrumb { padding: 16px 0; font-size: 0.875rem; color: var(--text-muted); }
.breadcrumb a { color: var(--green); }
.breadcrumb a:hover { text-decoration: underline; }
.breadcrumb span { margin: 0 8px; }

.menu-layout { display: grid; grid-template-columns: 260px 1fr; gap: 40px; padding-bottom: 80px; }
.menu-sidebar { position: sticky; top: 96px; align-self: start; max-height: calc(100vh - 120px); overflow-y: auto; padding-right: 16px; }
.menu-sidebar-group { margin-bottom: 24px; }
.menu-sidebar-group h3 { font-size: 0.75rem; font-weight: 600; text-transform: uppercase; letter-spacing: 0.08em; color: var(--text-muted); margin-bottom: 8px; padding: 0 12px; }
.menu-sidebar a { display: block; padding: 8px 12px; font-size: 0.9375rem; color: var(--text); border-radius: var(--radius-sm); transition: all var(--transition); }
.menu-sidebar a:hover { background: var(--green-light); color: var(--green); }
.menu-sidebar a.active { background: var(--green); color: var(--white); font-weight: 500; }

.menu-section { margin-bottom: 56px; }
.menu-section h2 { font-size: 1.75rem; margin-bottom: 8px; padding-bottom: 16px; border-bottom: 2px solid var(--gray-200); }
.menu-section-desc { color: var(--text-light); margin-bottom: 32px; font-size: 0.9375rem; }

.menu-items-grid { display: grid; grid-template-columns: repeat(auto-fill, minmax(220px, 1fr)); gap: 24px; }
.menu-item-card { background: var(--white); border-radius: var(--radius-md); overflow: hidden; border: 1px solid var(--gray-200); transition: all var(--transition); }
.menu-item-card:hover { box-shadow: var(--shadow-lg); border-color: var(--green); transform: translateY(-2px); }
.menu-item-image { height: 180px; display: flex; align-items: center; justify-content: center; font-size: 0.8125rem; color: var(--text-muted); }
.menu-item-info { padding: 16px; }
.menu-item-info h4 { font-size: 0.9375rem; font-weight: 600; margin-bottom: 4px; }
.menu-item-info p { font-size: 0.8125rem; color: var(--text-muted); }
.menu-item-cals { font-size: 0.75rem; color: var(--text-muted); margin-top: 4px; }

/* ===== REWARDS PAGE ===== */
.rewards-hero { background: linear-gradient(135deg, var(--green) 0%, var(--forest) 100%); color: var(--white); text-align: center; padding: 100px 0 80px; }
.rewards-hero h1 { font-size: 3rem; margin-bottom: 16px; color: var(--white); }
.rewards-hero p { font-size: 1.125rem; opacity: 0.9; max-width: 600px; margin: 0 auto 32px; }

.how-it-works { background: var(--gray-50); }
.steps-grid { display: grid; grid-template-columns: repeat(3, 1fr); gap: 32px; }
.step-card { text-align: center; padding: 32px; background: var(--white); border-radius: var(--radius-lg); box-shadow: var(--shadow-sm); }
.step-number { width: 56px; height: 56px; border-radius: 50%; background: var(--green); color: var(--white); display: flex; align-items: center; justify-content: center; font-family: var(--font-heading); font-weight: 700; font-size: 1.25rem; margin: 0 auto 20px; }
.step-card h3 { font-size: 1.125rem; margin-bottom: 8px; }
.step-card p { font-size: 0.9375rem; color: var(--text-light); line-height: 1.6; }

/* Tiers */
.tiers-section { background: var(--white); }
.tiers-grid { display: grid; grid-template-columns: repeat(3, 1fr); gap: 24px; }
.tier-card { border-radius: var(--radius-lg); padding: 36px; border: 2px solid var(--gray-200); transition: all var(--transition); }
.tier-card:hover { box-shadow: var(--shadow-lg); }
.tier-card.green-tier { border-color: var(--green); }
.tier-card.gold-tier { border-color: var(--gold); }
.tier-card.reserve-tier { border-color: var(--reserve-purple); }
.tier-badge { display: inline-flex; align-items: center; gap: 8px; padding: 6px 16px; border-radius: var(--radius-full); font-size: 0.875rem; font-weight: 600; margin-bottom: 16px; }
.tier-card.green-tier .tier-badge { background: var(--green-light); color: var(--green); }
.tier-card.gold-tier .tier-badge { background: var(--gold-light); color: #8B6914; }
.tier-card.reserve-tier .tier-badge { background: var(--reserve-light); color: var(--reserve-purple); }
.tier-threshold { font-size: 0.875rem; color: var(--text-muted); margin-bottom: 20px; }
.tier-benefits { list-style: none; }
.tier-benefits li { padding: 8px 0; font-size: 0.9375rem; display: flex; align-items: flex-start; gap: 10px; }
.tier-benefits li::before { content: ''; flex-shrink: 0; width: 20px; height: 20px; margin-top: 2px; background: var(--green); border-radius: 50%; display: flex; align-items: center; justify-content: center; background-image: url("data:image/svg+xml,%3Csvg viewBox='0 0 16 16' fill='white' xmlns='http://www.w3.org/2000/svg'%3E%3Cpath d='M13.3 4.3L6 11.6 2.7 8.3a1 1 0 00-1.4 1.4l4 4a1 1 0 001.4 0l8-8a1 1 0 10-1.4-1.4z'/%3E%3C/svg%3E"); background-size: 10px; background-repeat: no-repeat; background-position: center; }
.tier-card.gold-tier .tier-benefits li::before { background-color: var(--gold); background-image: url("data:image/svg+xml,%3Csvg viewBox='0 0 16 16' fill='white' xmlns='http://www.w3.org/2000/svg'%3E%3Cpath d='M13.3 4.3L6 11.6 2.7 8.3a1 1 0 00-1.4 1.4l4 4a1 1 0 001.4 0l8-8a1 1 0 10-1.4-1.4z'/%3E%3C/svg%3E"); background-size: 10px; background-repeat: no-repeat; background-position: center; }
.tier-card.reserve-tier .tier-benefits li::before { background-color: var(--reserve-purple); background-image: url("data:image/svg+xml,%3Csvg viewBox='0 0 16 16' fill='white' xmlns='http://www.w3.org/2000/svg'%3E%3Cpath d='M13.3 4.3L6 11.6 2.7 8.3a1 1 0 00-1.4 1.4l4 4a1 1 0 001.4 0l8-8a1 1 0 10-1.4-1.4z'/%3E%3C/svg%3E"); background-size: 10px; background-repeat: no-repeat; background-position: center; }

/* Redemption Tabs */
.redemption-section { background: var(--gray-50); }
.redemption-tabs { display: flex; gap: 8px; margin-bottom: 32px; flex-wrap: wrap; }
.redemption-tab { padding: 10px 20px; border-radius: var(--radius-full); font-weight: 600; font-size: 0.9375rem; background: var(--white); border: 2px solid var(--gray-200); color: var(--text-muted); transition: all var(--transition); }
.redemption-tab:hover { border-color: var(--green); color: var(--green); }
.redemption-tab.active { background: var(--green); border-color: var(--green); color: var(--white); }
.redemption-content { display: none; background: var(--white); padding: 40px; border-radius: var(--radius-lg); box-shadow: var(--shadow-sm); }
.redemption-content.active { display: flex; gap: 32px; align-items: center; }
.redemption-info { flex: 1; }
.redemption-stars { font-size: 2.5rem; font-weight: 700; color: var(--green); font-family: var(--font-heading); margin-bottom: 8px; }
.redemption-label { font-size: 1.25rem; font-weight: 600; margin-bottom: 8px; }
.redemption-value { font-size: 0.9375rem; color: var(--text-muted); }
.redemption-icon { width: 120px; height: 120px; border-radius: var(--radius-lg); display: flex; align-items: center; justify-content: center; font-size: 3rem; flex-shrink: 0; }

/* Partnerships */
.partnerships-section { background: var(--white); }
.partners-grid { display: grid; grid-template-columns: repeat(2, 1fr); gap: 24px; }
.partner-card { display: flex; align-items: center; gap: 24px; padding: 32px; border-radius: var(--radius-lg); border: 1px solid var(--gray-200); transition: box-shadow var(--transition); }
.partner-card:hover { box-shadow: var(--shadow-md); }
.partner-logo { width: 64px; height: 64px; border-radius: var(--radius-md); background: var(--gray-100); display: flex; align-items: center; justify-content: center; font-weight: 700; font-size: 0.75rem; color: var(--text-muted); flex-shrink: 0; }
.partner-info h3 { font-size: 1rem; margin-bottom: 4px; }
.partner-info p { font-size: 0.875rem; color: var(--text-light); line-height: 1.5; }

/* App Download */
.app-download { background: var(--forest); color: var(--white); text-align: center; }
.app-download h2 { color: var(--white); font-size: 2rem; margin-bottom: 12px; }
.app-download p { opacity: 0.85; max-width: 500px; margin: 0 auto 32px; }
.app-badges { display: flex; gap: 16px; justify-content: center; }
.app-badge { display: inline-flex; align-items: center; gap: 10px; background: rgba(255,255,255,0.12); border: 1px solid rgba(255,255,255,0.25); padding: 12px 24px; border-radius: var(--radius-md); color: var(--white); font-weight: 500; transition: background var(--transition); }
.app-badge:hover { background: rgba(255,255,255,0.2); }

/* ===== GIFT CARDS PAGE ===== */
.gift-hero { background: linear-gradient(135deg, var(--cream) 0%, #E8D5B5 100%); text-align: center; padding: 80px 0; }
.gift-hero h1 { font-size: 3rem; color: var(--forest); margin-bottom: 16px; }
.gift-hero p { font-size: 1.125rem; color: var(--text-light); max-width: 550px; margin: 0 auto; }

.carousel-section { padding: 56px 0; }
.carousel-header { display: flex; align-items: center; justify-content: space-between; margin-bottom: 24px; }
.carousel-header h2 { font-size: 1.5rem; }
.carousel-controls { display: flex; gap: 8px; }
.carousel-btn { width: 40px; height: 40px; border-radius: 50%; border: 2px solid var(--gray-300); display: flex; align-items: center; justify-content: center; transition: all var(--transition); color: var(--text); }
.carousel-btn:hover:not(:disabled) { border-color: var(--green); color: var(--green); background: var(--green-light); }
.carousel-btn:disabled { opacity: 0.35; cursor: not-allowed; }
.carousel-btn svg { width: 18px; height: 18px; }
.carousel-track-wrapper { overflow: hidden; border-radius: var(--radius-md); }
.carousel-track { display: flex; gap: 20px; transition: transform 0.4s cubic-bezier(0.25, 0.46, 0.45, 0.94); }
.gift-card-item { flex: 0 0 calc(25% - 15px); border-radius: var(--radius-md); overflow: hidden; cursor: pointer; transition: all var(--transition); }
.gift-card-item:hover { transform: translateY(-4px); box-shadow: var(--shadow-lg); }
.gift-card-visual { height: 160px; display: flex; align-items: center; justify-content: center; color: var(--white); font-weight: 600; font-size: 0.9375rem; border-radius: var(--radius-md) var(--radius-md) 0 0; text-align: center; padding: 16px; }
.gift-card-label { padding: 12px 16px; font-size: 0.875rem; font-weight: 500; background: var(--white); border: 1px solid var(--gray-200); border-top: 0; border-radius: 0 0 var(--radius-md) var(--radius-md); }

.category-nav { display: flex; gap: 8px; margin-bottom: 40px; flex-wrap: wrap; padding: 0 24px; }
.category-nav button { padding: 8px 20px; border-radius: var(--radius-full); font-weight: 500; font-size: 0.875rem; background: var(--gray-100); color: var(--text-muted); transition: all var(--transition); }
.category-nav button:hover { background: var(--green-light); color: var(--green); }
.category-nav button.active { background: var(--green); color: var(--white); }

.category-carousel-section { margin-bottom: 48px; }

/* Business Gifting */
.business-gifting { background: var(--forest); color: var(--white); border-radius: var(--radius-lg); padding: 56px; display: flex; align-items: center; gap: 48px; margin: 40px 0; }
.business-gifting h2 { font-size: 2rem; color: var(--white); margin-bottom: 12px; }
.business-gifting p { opacity: 0.85; margin-bottom: 28px; line-height: 1.7; }
.business-gifting-visual { flex: 0 0 280px; height: 200px; background: rgba(255,255,255,0.08); border-radius: var(--radius-md); display: flex; align-items: center; justify-content: center; color: rgba(255,255,255,0.5); font-size: 0.875rem; }

/* eGift Info */
.egift-section { background: var(--cream-bg); border-radius: var(--radius-lg); padding: 48px; text-align: center; margin-bottom: 48px; }
.egift-section h2 { font-size: 1.75rem; margin-bottom: 16px; color: var(--forest); }
.egift-section p { max-width: 640px; margin: 0 auto 12px; color: var(--text-light); line-height: 1.7; }
.egift-actions { margin-top: 24px; display: flex; gap: 12px; justify-content: center; flex-wrap: wrap; }

/* FAQ */
.faq-section { padding: 56px 0; }
.faq-item { border-bottom: 1px solid var(--gray-200); }
.faq-question { width: 100%; display: flex; align-items: center; justify-content: space-between; padding: 20px 0; font-size: 1rem; font-weight: 600; color: var(--text); text-align: left; }
.faq-question svg { flex-shrink: 0; width: 20px; height: 20px; transition: transform var(--transition); color: var(--green); }
.faq-question.active svg { transform: rotate(180deg); }
.faq-answer { max-height: 0; overflow: hidden; transition: max-height 0.3s ease; }
.faq-answer-inner { padding: 0 0 20px; color: var(--text-light); line-height: 1.7; font-size: 0.9375rem; }

/* ===== STORE LOCATOR PAGE ===== */
.locator-layout { display: grid; grid-template-columns: 420px 1fr; min-height: calc(100vh - 72px); }
.locator-sidebar { background: var(--white); border-right: 1px solid var(--gray-200); overflow-y: auto; }
.locator-controls { padding: 24px; border-bottom: 1px solid var(--gray-200); }
.order-type-toggle { display: flex; background: var(--gray-100); border-radius: var(--radius-full); padding: 4px; margin-bottom: 16px; }
.order-type-btn { flex: 1; padding: 10px; border-radius: var(--radius-full); font-weight: 500; font-size: 0.875rem; text-align: center; transition: all var(--transition); color: var(--text-muted); }
.order-type-btn.active { background: var(--white); color: var(--text); box-shadow: var(--shadow-sm); }
.search-input-wrap { position: relative; margin-bottom: 12px; }
.search-input-wrap svg { position: absolute; left: 14px; top: 50%; transform: translateY(-50%); width: 18px; height: 18px; color: var(--text-muted); }
.search-input { width: 100%; padding: 12px 12px 12px 42px; border: 2px solid var(--gray-200); border-radius: var(--radius-full); font-size: 0.9375rem; font-family: var(--font-body); transition: border-color var(--transition); outline: none; }
.search-input:focus { border-color: var(--green); }
.search-input::placeholder { color: var(--gray-400); }
.search-suggestions { position: absolute; top: 100%; left: 0; right: 0; background: var(--white); border: 1px solid var(--gray-200); border-radius: var(--radius-md); box-shadow: var(--shadow-lg); z-index: 10; display: none; overflow: hidden; }
.search-suggestions.active { display: block; }
.suggestion-item { padding: 12px 16px; font-size: 0.9375rem; cursor: pointer; transition: background var(--transition); display: flex; align-items: center; gap: 10px; }
.suggestion-item:hover { background: var(--green-light); }
.suggestion-item svg { width: 16px; height: 16px; color: var(--text-muted); flex-shrink: 0; }
.filter-controls { display: flex; gap: 8px; }
.filter-btn { display: inline-flex; align-items: center; gap: 6px; padding: 8px 16px; border: 1px solid var(--gray-200); border-radius: var(--radius-full); font-size: 0.875rem; font-weight: 500; color: var(--text); transition: all var(--transition); }
.filter-btn:hover { border-color: var(--green); color: var(--green); }
.filter-btn svg { width: 16px; height: 16px; }

.filter-panel { display: none; padding: 24px; border-bottom: 1px solid var(--gray-200); background: var(--gray-50); }
.filter-panel.active { display: block; }
.filter-group { margin-bottom: 16px; }
.filter-group h4 { font-size: 0.8125rem; font-weight: 600; text-transform: uppercase; letter-spacing: 0.05em; color: var(--text-muted); margin-bottom: 10px; }
.filter-option { display: flex; align-items: center; gap: 10px; padding: 6px 0; cursor: pointer; font-size: 0.9375rem; }
.filter-checkbox { width: 18px; height: 18px; border: 2px solid var(--gray-300); border-radius: 4px; display: flex; align-items: center; justify-content: center; transition: all var(--transition); flex-shrink: 0; }
.filter-option.checked .filter-checkbox { background: var(--green); border-color: var(--green); }

.store-results { padding: 0; }
.store-card { padding: 20px 24px; border-bottom: 1px solid var(--gray-100); cursor: pointer; transition: background var(--transition); }
.store-card:hover { background: var(--green-light); }
.store-card h3 { font-size: 1rem; font-weight: 600; margin-bottom: 4px; }
.store-card-address { font-size: 0.875rem; color: var(--text-muted); margin-bottom: 6px; }
.store-card-hours { font-size: 0.8125rem; color: var(--green); font-weight: 500; margin-bottom: 8px; }
.store-card-features { display: flex; gap: 6px; flex-wrap: wrap; }
.store-feature-tag { padding: 2px 10px; background: var(--gray-100); border-radius: var(--radius-full); font-size: 0.75rem; color: var(--text-muted); }
.store-card-actions { margin-top: 12px; display: flex; gap: 10px; }

.map-container { background: #E8E8E8; display: flex; align-items: center; justify-content: center; position: relative; }
.map-placeholder { text-align: center; color: var(--text-muted); }
.map-placeholder svg { width: 64px; height: 64px; margin-bottom: 12px; opacity: 0.4; }
.map-placeholder p { font-size: 0.9375rem; }

/* ===== FOOTER ===== */
.site-footer { background: var(--forest); color: rgba(255,255,255,0.85); padding: 64px 0 32px; }
.footer-grid { display: grid; grid-template-columns: repeat(5, 1fr); gap: 32px; margin-bottom: 48px; }
.footer-col h3 { font-size: 0.875rem; font-weight: 600; color: var(--white); margin-bottom: 16px; text-transform: uppercase; letter-spacing: 0.05em; }
.footer-col a { display: block; padding: 4px 0; font-size: 0.875rem; color: rgba(255,255,255,0.7); transition: color var(--transition); }
.footer-col a:hover { color: var(--white); }
.footer-col .accordion-toggle { display: none; }
.footer-bottom { border-top: 1px solid rgba(255,255,255,0.12); padding-top: 24px; display: flex; align-items: center; justify-content: space-between; flex-wrap: wrap; gap: 16px; }
.footer-legal { display: flex; gap: 24px; flex-wrap: wrap; }
.footer-legal a { font-size: 0.8125rem; color: rgba(255,255,255,0.6); transition: color var(--transition); }
.footer-legal a:hover { color: var(--white); }
.footer-social { display: flex; gap: 12px; }
.footer-social a { width: 36px; height: 36px; border-radius: 50%; background: rgba(255,255,255,0.1); display: flex; align-items: center; justify-content: center; transition: background var(--transition); }
.footer-social a:hover { background: rgba(255,255,255,0.2); }
.footer-social svg { width: 18px; height: 18px; fill: var(--white); }
.footer-copyright { text-align: center; margin-top: 24px; font-size: 0.8125rem; color: rgba(255,255,255,0.45); }

/* ===== COOKIE BANNER ===== */
.cookie-banner { position: fixed; bottom: 0; left: 0; right: 0; background: var(--white); box-shadow: 0 -4px 20px rgba(0,0,0,0.1); padding: 24px; z-index: 200; transform: translateY(0); transition: transform 0.4s ease; }
.cookie-banner.hidden { transform: translateY(100%); pointer-events: none; }
.cookie-inner { max-width: var(--max-width); margin: 0 auto; display: flex; align-items: center; gap: 24px; }
.cookie-text h3 { font-size: 1rem; font-weight: 600; margin-bottom: 4px; }
.cookie-text p { font-size: 0.875rem; color: var(--text-muted); line-height: 1.5; }
.cookie-actions { display: flex; gap: 12px; flex-shrink: 0; }

/* ===== RESPONSIVE ===== */
@media (max-width: 1024px) {
  .promo-grid { grid-template-columns: 1fr; }
  .seasonal-grid { grid-template-columns: 1fr; }
  .tiers-grid { grid-template-columns: 1fr; }
  .partners-grid { grid-template-columns: 1fr; }
  .menu-layout { grid-template-columns: 1fr; }
  .menu-sidebar { position: static; display: flex; gap: 8px; flex-wrap: wrap; max-height: none; overflow: visible; padding: 0; margin-bottom: 24px; }
  .menu-sidebar-group { margin-bottom: 8px; display: flex; gap: 4px; flex-wrap: wrap; align-items: center; }
  .menu-sidebar-group h3 { margin-bottom: 0; padding: 8px 12px; }
  .menu-sidebar a { padding: 6px 14px; font-size: 0.8125rem; white-space: nowrap; border: 1px solid var(--gray-200); border-radius: var(--radius-full); }
  .locator-layout { grid-template-columns: 1fr; }
  .map-container { min-height: 300px; order: -1; }
  .business-gifting { flex-direction: column; padding: 40px; }
  .business-gifting-visual { flex: none; width: 100%; height: 160px; }
  .nondairy-banner { flex-direction: column; padding: 40px; }
  .nondairy-visual { flex: none; width: 100%; height: 160px; }
  .gift-card-item { flex: 0 0 calc(33.333% - 14px); }
}

@media (max-width: 768px) {
  .hero h1 { font-size: 2.5rem; }
  .hero-content { padding: 60px 0; }
  .hero-image { display: none; }
  .section { padding: 56px 0; }
  .section-title { font-size: 1.75rem; }
  .nav-main, .nav-actions { display: none; }
  .mobile-menu-btn { display: flex; flex-direction: column; justify-content: center; }
  .promo-card-inner { flex-direction: column; }
  .promo-card-image { min-width: 0; }
  .promo-full { padding: 32px; min-height: auto; }
  .promo-full-content h2 { font-size: 1.5rem; }
  .steps-grid { grid-template-columns: 1fr; }
  .rewards-hero h1 { font-size: 2.25rem; }
  .rewards-hero { padding: 64px 0; }
  .redemption-content.active { flex-direction: column; text-align: center; }
  .footer-grid { grid-template-columns: 1fr; gap: 0; }
  .footer-col { border-bottom: 1px solid rgba(255,255,255,0.1); }
  .footer-col h3 { padding: 16px 0; margin-bottom: 0; cursor: pointer; display: flex; align-items: center; justify-content: space-between; }
  .footer-col h3::after { content: '+'; font-size: 1.25rem; font-weight: 300; color: rgba(255,255,255,0.5); transition: transform var(--transition); }
  .footer-col.expanded h3::after { content: '\2212'; }
  .footer-col .footer-links { max-height: 0; overflow: hidden; transition: max-height 0.3s ease; }
  .footer-col.expanded .footer-links { max-height: 300px; }
  .footer-col .footer-links a { padding: 8px 0; }
  .cookie-inner { flex-direction: column; text-align: center; }
  .cookie-actions { width: 100%; }
  .cookie-actions .btn { flex: 1; }
  .gift-card-item { flex: 0 0 calc(50% - 10px); }
  .locator-controls { padding: 16px; }
  .gift-hero h1, .rewards-hero h1 { font-size: 2rem; }
  .app-badges { flex-direction: column; align-items: center; }
  .header-inner { height: 60px; }
}

@media (max-width: 480px) {
  .hero h1 { font-size: 2rem; }
  .hero-actions { flex-direction: column; }
  .hero-actions .btn { width: 100%; }
  .promo-card-content { padding: 28px; }
  .promo-card-content h2 { font-size: 1.375rem; }
  .gift-card-item { flex: 0 0 calc(100% - 0px); }
  .redemption-tabs { gap: 6px; }
  .redemption-tab { padding: 8px 14px; font-size: 0.8125rem; }
  .container { padding: 0 16px; }
}
